let parts=preset('rocket'), selected=null, placing=null, ghost=null, flight=null, category='すべて', mode='select', bayMode='vab', pointerDown=null, saveDrag=null, pendingPose=null, timer, accumulated=0;
const assets=new Map(), objects=new Map(), raycaster=new T.Raycaster(), mouse=new T.Vector2(), history=[], future=[], keys=new Set();
function notify(msg){$('#toast').textContent=msg;$('#toast').classList.add('show');clearTimeout(timer);timer=setTimeout(()=>$('#toast').classList.remove('show'),3600);}
function snapshot(){return JSON.stringify(parts);}function checkpoint(){history.push(snapshot());if(history.length>60)history.shift();future.length=0;}
function undo(){if(!history.length||flight)return;future.push(snapshot());parts=JSON.parse(history.pop());cancelPlacement();rebuild();notify('元に戻しました');}function redo(){if(!future.length||flight)return;history.push(snapshot());parts=JSON.parse(future.pop());rebuild();}
function cloneModel(type){const model=assets.get(type).clone(true);model.traverse(m=>{if(m.isMesh){m.castShadow=true;m.receiveShadow=true;}});return model;}
function rebuild(){gizmo.detach();craftRoot.clear();objects.clear();for(const p of parts){const o=new T.Group();o.userData.partId=p.id;o.add(cloneModel(p.type));o.position.fromArray(p.p);o.rotation.set(...p.r);craftRoot.add(o);objects.set(p.id,o);}for(const p of parts){if(p.type!=='wheel')continue;const parent=parts.find(a=>a.id===p.parent);if(!parent)continue;const wheel=objects.get(p.id),from=new T.Vector3(...p.p),to=new T.Vector3(parent.p[0],parent.p[1]-.25,p.p[2]),delta=to.clone().sub(from);if(delta.length()>.2&&delta.length()<3){const mount=cloneModel('truss');mount.position.copy(from).add(to).multiplyScalar(.5);mount.quaternion.setFromUnitVectors(new T.Vector3(0,1,0),delta.clone().normalize());mount.scale.set(.12,delta.length(),.12);craftRoot.add(mount);wheel.updateMatrixWorld();const world=mount.matrixWorld.clone();craftRoot.updateMatrixWorld(true);wheel.attach(mount);}}if(selected&&!objects.has(selected))selected=null;select(selected);updateInfo();}
function disposeMarkers(){for(const c of markers.children){c.geometry?.dispose();c.material?.dispose();}markers.clear();}
function showNodes(){disposeMarkers();if(!placing||$('#attach').value!=='node')return;for(const p of parts){const o=objects.get(p.id);o.updateWorldMatrix(true,false);for(const n of nodes(p.type)){const m=new T.Mesh(new T.SphereGeometry(.065,8,6),new T.MeshBasicMaterial({color:'#a4e4df',transparent:true,opacity:.65,depthTest:false}));m.position.copy(o.localToWorld(new T.Vector3(...n.slice(0,3))));markers.add(m);}}}
const highlight=new T.BoxHelper(new T.Object3D(),'#eeae6d');highlight.visible=false;scene.add(highlight);
function select(id){selected=id;const o=objects.get(id);highlight.visible=!!o&&!flight;if(o){highlight.setFromObject(o);if(mode!=='select'&&!flight)gizmo.attach(o);else gizmo.detach();}else gizmo.detach();renderInspector();}
function setMode(next){mode=next;cancelPlacement();$$('[data-mode]').forEach(b=>b.classList.toggle('active',b.dataset.mode===mode));if(mode!=='select')gizmo.setMode(mode);select(selected);}
function updateInfo(){const st=flight?flight.stats:statistics(parts);$('#mass').textContent=(st.mass/1000).toFixed(2);$('#twr').textContent=st.twr.toFixed(2);$('#dv').textContent=Math.round(st.dv).toLocaleString();$('#count').textContent=(flight?flight.parts:parts).length;comMarker.position.copy(st.com);const warnings=[];const hasControl=parts.some(p=>PARTS[p.type].control),engines=parts.filter(p=>PARTS[p.type].thrust),roots=parts.filter(p=>!p.parent);warnings.push([hasControl,'制御ユニット'+(hasControl?'接続済み':'がありません')]);warnings.push([roots.length===1,roots.length===1?'接続ツリー正常':`独立した機体が ${roots.length} 個あります`]);if(engines.length)warnings.push([st.fuel>0||engines.every(p=>PARTS[p.type].water),st.fuel>0?'推進剤搭載済み':'燃料タンク未搭載']);if($('#environment').value==='land'&&engines.length)warnings.push([st.twr>1,st.twr>1?'垂直離陸に必要な推力あり':'垂直離陸には推力が不足']);$('#checks').innerHTML=warnings.map(([ok,s])=>`<div class="check ${ok?'':'warn'}"><i>${ok?'✓':'!'}</i>${s}</div>`).join('');const stages=[...new Set(parts.filter(p=>PARTS[p.type].thrust||PARTS[p.type].decoupler).map(p=>p.stage))].sort();$('#stages').innerHTML=stages.length?stages.map(n=>`<div class="stageitem"><b>${String(n).padStart(2,'0')}</b><span>${parts.filter(p=>p.stage===n&&(PARTS[p.type].thrust||PARTS[p.type].decoupler)).map(p=>PARTS[p.type].code).join(' · ')}</span></div>`).join(''):'<p class="muted">推進器・分離リングがありません</p>';}
function renderInspector(){const p=parts.find(p=>p.id===selected),root=$('#selection');if(!p){root.innerHTML='<p class="muted">機体の部品をクリックすると<br>位置・回転・段を編集できます。</p>';return;}const d=PARTS[p.type];root.innerHTML=`<div class="parttitle"><b>${d.name}</b><small>${d.code}</small></div><p class="desc">${d.desc}</p><div class="xyz"><span>m</span>${p.p.map((v,i)=>`<input aria-label="位置 ${'XYZ'[i]}" data-field="p" data-axis="${i}" type="number" step="0.1" value="${v.toFixed(2)}">`).join('')}</div><div class="xyz"><span>°</span>${p.r.map((v,i)=>`<input aria-label="回転 ${'XYZ'[i]}" data-field="r" data-axis="${i}" type="number" step="15" value="${Math.round(v*180/Math.PI)}">`).join('')}</div><label class="field">作動ステージ<select id="partStage">${Array.from({length:10},(_,i)=>`<option value="${i}" ${p.stage===i?'selected':''}>${String(i).padStart(2,'0')}</option>`).join('')}</select></label><div class="actions"><button id="duplicate">複製</button><button id="deletePart" class="danger">枝ごと削除</button></div>`;
 root.querySelectorAll('[data-field]').forEach(el=>el.onchange=()=>{const v=Number(el.value);if(!Number.isFinite(v)||Math.abs(v)>1000)return;checkpoint();const obj=objects.get(p.id);obj.updateMatrix();const before=obj.matrix.clone();p[el.dataset.field][+el.dataset.axis]=el.dataset.field==='r'?v*Math.PI/180:v;obj.position.fromArray(p.p);obj.rotation.set(...p.r);obj.updateMatrix();transformChildren(p.id,before,obj.matrix);rebuild();});$('#partStage').onchange=e=>{checkpoint();p.stage=+e.target.value;updateInfo();};$('#duplicate').onclick=()=>beginPlacement(p.type);$('#deletePart').onclick=deleteSelected;
}
function transformChildren(id,before,after){const delta=after.clone().multiply(before.clone().invert()),ids=descendants(parts,id);ids.delete(id);for(const p of parts)if(ids.has(p.id)){const o=objects.get(p.id);o.updateMatrix();const m=delta.clone().multiply(o.matrix);m.decompose(o.position,o.quaternion,o.scale);p.p=o.position.toArray();p.r=[o.rotation.x,o.rotation.y,o.rotation.z];}}
