function cancelPlacement(){placing=null;pendingPose=null;if(ghost){scene.remove(ghost);ghost.traverse(m=>{if(m.isMesh){const list=Array.isArray(m.material)?m.material:[m.material];list.forEach(x=>x.dispose());}});ghost=null;}disposeMarkers();$('#placement').hidden=true;$$('.partcard').forEach(b=>b.classList.remove('active'));}
function beginPlacement(type){if(flight)return;cancelPlacement();gizmo.detach();placing=type;ghost=cloneModel(type);ghost.traverse(o=>{if(o.isMesh){const tint=m=>{m=m.clone();m.transparent=true;m.opacity=.5;m.depthWrite=false;return m;};o.material=Array.isArray(o.material)?o.material.map(tint):tint(o.material);o.castShadow=false;}});scene.add(ghost);ghost.visible=false;$('#placement').hidden=false;$('#placement').firstChild.textContent=PARTS[type].name+' · 取付位置をクリック ';$$('.partcard').forEach(b=>b.classList.toggle('active',b.dataset.type===type));showNodes();}
function pointer(e){const r=canvas.getBoundingClientRect();mouse.set((e.clientX-r.left)/r.width*2-1,-(e.clientY-r.top)/r.height*2+1);raycaster.setFromCamera(mouse,camera);}
function hitPart(){const hits=raycaster.intersectObjects([...objects.values()],true);for(const h of hits){let o=h.object;while(o&&!o.userData.partId)o=o.parent;if(o)return {...h,id:o.userData.partId,root:o};}return null;}
function posePlacement(e){if(!placing)return;pointer(e);const hit=hitPart(),kind=$('#attach').value;let pos=new T.Vector3(),q=new T.Quaternion(),parent=hit?.id??null;const horizontal=bayMode==='sph';if(horizontal)q.setFromAxisAngle(new T.Vector3(1,0,0),Math.PI/2);
 if(hit&&kind==='node'){let best=null,dist=Infinity;hit.root.updateWorldMatrix(true,false);for(const n of nodes(parts.find(p=>p.id===hit.id).type)){const pt=hit.root.localToWorld(new T.Vector3(...n.slice(0,3))),d=pt.distanceTo(hit.point);if(d<dist){dist=d;best={point:pt,normal:new T.Vector3(...n.slice(3)).transformDirection(hit.root.matrixWorld)};}}
 let anchor=new T.Vector3();if(placing==='wing'){q.setFromUnitVectors(new T.Vector3(1,0,0),best.normal);}else{q.copy(hit.root.quaternion);let score=-Infinity;for(const n of nodes(placing)){const normal=new T.Vector3(...n.slice(3)).applyQuaternion(q),s=normal.dot(best.normal.clone().negate());if(s>score){score=s;anchor.set(...n.slice(0,3));}}}pos.copy(best.point).sub(anchor.applyQuaternion(q));
 }else if(hit&&kind==='surface'){const normal=hit.face.normal.clone().transformDirection(hit.object.matrixWorld);const source=placing==='wing'?new T.Vector3(1,0,0):new T.Vector3(0,1,0);q.setFromUnitVectors(source,normal);pos.copy(hit.point);if(placing!=='wing')pos.addScaledVector(normal,PARTS[placing].size[1]/2);
 }else{const plane=new T.Plane(new T.Vector3(0,1,0),0);if(!raycaster.ray.intersectPlane(plane,pos))return;pos.y=horizontal?PARTS[placing].size[2]/2:PARTS[placing].size[1]/2;parent=selected||parts[0]?.id||null;if($('#snap').checked)pos.divideScalar(.25).round().multiplyScalar(.25);}
 ghost.position.copy(pos);ghost.quaternion.copy(q);ghost.visible=true;pendingPose={pos,q,parent};}
function place(){if(!pendingPose)return;const sym=$('#symmetry').value,count=sym==='mirror'?2:+sym;if(parts.length+count>400){notify('部品上限は400です');return;}checkpoint();const created=[];for(let i=0;i<count;i++){const pos=pendingPose.pos.clone(),q=pendingPose.q.clone();if(sym==='mirror'&&i){pos.x=-pos.x;const matrix=new T.Matrix4().makeRotationFromQuaternion(q),reflect=new T.Matrix4().makeScale(-1,1,1);matrix.premultiply(reflect).multiply(reflect);q.setFromRotationMatrix(matrix);if(placing==='wing')q.multiply(new T.Quaternion().setFromAxisAngle(new T.Vector3(0,1,0),Math.PI));}else if(i){const a=i*2*Math.PI/count,axis=bayMode==='vab'?new T.Vector3(0,1,0):new T.Vector3(0,0,1),rot=new T.Quaternion().setFromAxisAngle(axis,a);pos.applyQuaternion(rot);q.premultiply(rot);}const e=new T.Euler().setFromQuaternion(q);created.push({id:crypto.randomUUID(),type:placing,p:pos.toArray(),r:[e.x,e.y,e.z],parent:pendingPose.parent,stage:0});}parts.push(...created);selected=created[0].id;rebuild();showNodes();notify(`${PARTS[placing].name} ×${count} を取り付けました`);}
canvas.addEventListener('pointerdown',e=>{pointerDown={x:e.clientX,y:e.clientY,button:e.button,wasGizmo:!!gizmo.axis};});canvas.addEventListener('pointermove',e=>{if(!flight)posePlacement(e);});canvas.addEventListener('pointerup',e=>{if(!pointerDown||pointerDown.button!==0||Math.hypot(e.clientX-pointerDown.x,e.clientY-pointerDown.y)>5||pointerDown.wasGizmo||gizmo.dragging||flight)return;if(placing){posePlacement(e);place();}else{pointer(e);select(hitPart()?.id??null);}});canvas.addEventListener('contextmenu',e=>e.preventDefault());
function frame(){const bounds=new T.Box3().setFromObject(craftRoot);if(bounds.isEmpty())return;const center=bounds.getCenter(new T.Vector3()),size=bounds.getSize(new T.Vector3()).length();controls.target.copy(center);camera.position.copy(center).add(new T.Vector3(1,.65,1.3).normalize().multiplyScalar(Math.max(7,size*1.35)));controls.update();}
function craftData(){return {version:1,name:$('#craftName').value,parts:structuredClone(parts)};}
