$('#examples').onclick=()=>{if(flight)return;showModal('<div class="eyebrow">START FROM A BLUEPRINT</div><h2>最初の一機を選ぶ</h2><p>見本機を改造して、設計を試せます。現在の機体は「元に戻す」で復元できます。</p><div class="examplegrid">'+Object.entries(examples).map(([k,v])=>`<button data-example="${k}"><b>${v[1]}</b><span>${v[0]}<br>${v[2]}</span></button>`).join('')+'</div>');$$('[data-example]').forEach(b=>b.onclick=()=>{const k=b.dataset.example;checkpoint();parts=preset(k);$('#craftName').value=examples[k][0];setBay(['plane','boat','sub','rover'].includes(k)?'sph':'vab');$('#environment').value=examples[k][3];selected=null;cancelPlacement();rebuild();frame();$('#modal').close();});};
$('#help').onclick=()=>showModal('<div class="eyebrow">WORKSHOP FIELD GUIDE</div><h2>設計から試験まで</h2><p>左の部品を選び、機体の取付位置をクリック。接続点・表面・自由配置を切り替え、対称配置で翼やブースターを取り付けられます。</p><div class="helpgrid"><b>右ドラッグ / ホイール</b><span>視点回転 / 拡大縮小</span><b>中ドラッグ</b><span>平行移動</span><b>G / R / Esc</b><span>移動 / 回転 / 配置取消・選択モード</span><b>F / Delete</b><span>機体全体を表示 / 選択した接続枝を削除</span><b>Ctrl+Z / Ctrl+Y</b><span>元に戻す / やり直す</span><b>試験 → Space</b><span>点火 / 次のステージ実行</span><b>Shift / Ctrl / X</b><span>推力を上げる / 下げる / 停止</span><b>W/S · A/D · Q/E</b><span>ピッチ · ヨー · ロール</span><b>バラスト</b><span>海面試験で注排水。増やすと重くなる</span></div><p>保存はこのブラウザ内。JSON出力で機体を持ち出せます。現版は局所的な試験場です。球形惑星・軌道・再突入熱・電力消費・破断応力は未実装。Δvは共通タンクと平均比推力からの参考値です。</p>');
function setBay(b){if(flight)return;bayMode=b;$('#vab').classList.toggle('active',b==='vab');$('#sph').classList.toggle('active',b==='sph');$('#bayno').textContent=b==='vab'?'01':'02';if(b==='sph')$('#environment').value='runway';showNodes();updateInfo();}
$('#vab').onclick=()=>setBay('vab');$('#sph').onclick=()=>setBay('sph');$('#frame').onclick=frame;$('#com').onclick=()=>{comMarker.visible=!comMarker.visible;$('#com').classList.toggle('active',comMarker.visible);};$('#undo').onclick=undo;$('#redo').onclick=redo;$$('[data-mode]').forEach(b=>b.onclick=()=>setMode(b.dataset.mode));$('#attach').onchange=showNodes;$('#snap').onchange=()=>{gizmo.setTranslationSnap($('#snap').checked?.25:null);gizmo.setRotationSnap($('#snap').checked?Math.PI/12:null);};$('#snap').onchange();$('#environment').onchange=updateInfo;
$('#save').onclick=()=>{try{localStorage.setItem('orbital-foundry-craft',JSON.stringify(craftData()));notify('このブラウザに機体を保存しました');}catch{notify('保存できませんでした。JSON出力を使ってください。');}};$('#load').onclick=()=>{if(flight)return;try{const s=localStorage.getItem('orbital-foundry-craft');if(!s){notify('保存された機体がありません');return;}loadData(JSON.parse(s));notify('保存した機体を読み込みました');}catch(e){notify(e.message);}};$('#export').onclick=()=>{const a=document.createElement('a');const url=URL.createObjectURL(new Blob([JSON.stringify(craftData(),null,2)],{type:'application/json'}));a.href=url;a.download=($('#craftName').value.replace(/[^\p{L}\p{N}_-]/gu,'_')||'craft')+'.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),5000);};$('#import').onclick=()=>{if(!flight)$('#file').click();};$('#file').onchange=async e=>{try{const file=e.target.files[0];if(!file)return;if(file.size>1000000)throw Error('機体ファイルが大きすぎます');loadData(JSON.parse(await file.text()));notify('機体を読み込みました');}catch(e){notify(e.message);}$('#file').value='';};
function disposeWorld(){testWorld.traverse(o=>{o.geometry?.dispose();if(o.material){const mats=Array.isArray(o.material)?o.material:[o.material];mats.forEach(m=>m.dispose());}});testWorld.clear();}
function buildTestWorld(environment){disposeWorld();if(environment==='water'){box(testWorld,[6000,1,6000],[0,-.8,0],new T.MeshStandardMaterial({color:'#164c64',metalness:.65,roughness:.2,transparent:true,opacity:.75}));const seaGrid=new T.GridHelper(600,60,'#35728a','#205267');seaGrid.position.y=-.25;testWorld.add(seaGrid);box(testWorld,[25,2,40],[-28,-1,0],mat('#8c9490'));}else{box(testWorld,[6000,2,6000],[0,-1.1,0],mat('#627569',.05,.95));box(testWorld,[18,.08,2200],[0,-.03,1000],mat('#3a4245',.1,.9));for(let z=-40;z<2100;z+=22)box(testWorld,[.25,.02,8],[0,.02,z],mat('#d8d7bd'));const g=new T.GridHelper(400,80,'#899e91','#6b8476');g.position.y=.015;testWorld.add(g);}
 for(let i=0;i<14;i++){const m=new T.Mesh(new T.ConeGeometry(100+i*8,70+i*7,5),mat(i%2?'#4c686b':'#59716d'));const a=i*2*Math.PI/14;m.position.set(Math.sin(a)*700,25,Math.cos(a)*700);testWorld.add(m);}}
const exhaust=[];function startFlight(){if(!parts.length){notify('まず機体を組み立ててください');return;}if(!parts.some(p=>PARTS[p.type].control)){notify('試験には制御ユニットが必要です');return;}if(parts.filter(p=>!p.parent).length!==1){notify('独立した部品を接続してから試験してください');return;}cancelPlacement();gizmo.detach();highlight.visible=false;comMarker.visible=false;flight=new Flight(parts,$('#environment').value);accumulated=0;buildTestWorld(flight.environment);testWorld.visible=true;bay.visible=false;scene.background=new T.Color('#8eb5c8');scene.fog=new T.Fog('#9fbdc5',300,2000);document.body.classList.add('flying');$('#flightHud').hidden=false;$('#launch').disabled=true;$('#throttle').value=0;$('#ballast').value=0;$('#ballastControl').hidden=!parts.some(p=>PARTS[p.type].ballast);$('#sas').classList.add('active');$('#sas').textContent='SAS ON';$('#brake').classList.add('active');$('#brake').textContent='BRAKE ON';controls.maxDistance=150;for(const p of parts){if(PARTS[p.type].thrust&&!PARTS[p.type].water){const flame=new T.Mesh(new T.ConeGeometry(.23,1.3,16),new T.MeshBasicMaterial({color:PARTS[p.type].air?'#76cdff':'#ffba60',transparent:true,opacity:.8,depthWrite:false}));flame.rotation.z=Math.PI;flame.position.y=-PARTS[p.type].size[1]/2-.5;flame.visible=false;objects.get(p.id).add(flame);exhaust.push({id:p.id,mesh:flame});}}craftRoot.position.copy(flight.pos);frame();notify('推力を調整してSpaceで点火。試験終了後は組立棟に戻れます。');}
function endFlight(){flight=null;exhaust.forEach(e=>{e.mesh.geometry.dispose();e.mesh.material.dispose();});exhaust.length=0;craftRoot.position.set(0,0,0);craftRoot.quaternion.identity();testWorld.visible=false;bay.visible=true;scene.background=new T.Color('#293c49');scene.fog=new T.Fog('#293c49',55,135);document.body.classList.remove('flying');$('#flightHud').hidden=true;$('#launch').disabled=false;controls.maxDistance=80;sun.position.set(12,24,12);sun.target.position.set(0,0,0);rebuild();frame();}
function stage(){if(!flight)return;const removed=flight.stageNext();for(const id of removed){const o=objects.get(id);if(o)o.visible=false;}notify(`ステージ ${String(flight.stage).padStart(2,'0')} 実行${removed.size?' / '+removed.size+' 部品分離':''}`);$('#brake').classList.toggle('active',flight.brake);$('#brake').textContent='BRAKE '+(flight.brake?'ON':'OFF');}
$('#launch').onclick=startFlight;$('#back').onclick=endFlight;$('#stage').onclick=stage;$('#throttle').oninput=e=>{if(flight)flight.throttle=+e.target.value/100;};$('#ballast').oninput=e=>{if(flight)flight.ballast=+e.target.value/100;};$('#sas').onclick=()=>{if(!flight)return;flight.sas=!flight.sas;$('#sas').classList.toggle('active',flight.sas);$('#sas').textContent='SAS '+(flight.sas?'ON':'OFF');};$('#brake').onclick=()=>{if(!flight)return;flight.brake=!flight.brake;$('#brake').classList.toggle('active',flight.brake);$('#brake').textContent='BRAKE '+(flight.brake?'ON':'OFF');};
window.addEventListener('keydown',e=>{if(['INPUT','SELECT','TEXTAREA'].includes(e.target.tagName)||$('#modal').open)return;keys.add(e.code);if(['Space','Delete','ArrowUp','ArrowDown'].includes(e.code))e.preventDefault();if(e.repeat)return;if(flight){if(e.code==='Space')stage();if(e.code==='KeyB')$('#brake').click();if(e.code==='KeyT')$('#sas').click();if(e.code==='KeyX'){flight.throttle=0;$('#throttle').value=0;}return;}if(e.ctrlKey&&e.code==='KeyZ'){e.preventDefault();undo();}else if(e.ctrlKey&&e.code==='KeyY'){e.preventDefault();redo();}else if(e.code==='Escape'){cancelPlacement();setMode('select');}else if(e.code==='KeyG')setMode('translate');else if(e.code==='KeyR')setMode('rotate');else if(e.code==='KeyF')frame();else if(e.code==='Delete')deleteSelected();});window.addEventListener('keyup',e=>keys.delete(e.code));window.addEventListener('blur',()=>keys.clear());
function resize(){const w=viewport.clientWidth,h=viewport.clientHeight;renderer.setSize(w,h,false);camera.aspect=w/h;camera.updateProjectionMatrix();}new ResizeObserver(resize).observe(viewport);
let last=performance.now(),infoTime=0;function animate(now){requestAnimationFrame(animate);const dt=Math.min((now-last)/1000,.1);last=now;if(flight){if(keys.has('ShiftLeft')||keys.has('ShiftRight'))flight.throttle=Math.min(1,flight.throttle+dt*.35);if(keys.has('ControlLeft')||keys.has('ControlRight'))flight.throttle=Math.max(0,flight.throttle-dt*.35);$('#throttle').value=flight.throttle*100;const prior=craftRoot.position.clone();accumulated+=dt;while(accumulated>=1/120){flight.step(1/120,{pitch:(keys.has('KeyW')?1:0)-(keys.has('KeyS')?1:0),yaw:(keys.has('KeyA')?1:0)-(keys.has('KeyD')?1:0),roll:(keys.has('KeyQ')?1:0)-(keys.has('KeyE')?1:0)});accumulated-=1/120;}craftRoot.position.copy(flight.pos);craftRoot.quaternion.copy(flight.q);const delta=craftRoot.position.clone().sub(prior);camera.position.add(delta);controls.target.add(delta);sun.position.copy(flight.pos).add(new T.Vector3(12,24,12));sun.target.position.copy(flight.pos);for(const e of exhaust){e.mesh.visible=flight.started&&flight.throttle>.01&&flight.fuelRatio>0&&flight.active.has(e.id)&&!flight.crashed;e.mesh.scale.y=.5+flight.throttle*(1+Math.sin(now*.09)*.08);}$('#alt').textContent=Math.max(-999,flight.pos.y-flight.floor).toFixed(1);$('#speed').textContent=flight.vel.length().toFixed(1);$('#vspeed').textContent=flight.vel.y.toFixed(1);$('#throttleVal').textContent=Math.round(flight.throttle*100)+'%';$('#flightStatus').textContent=flight.crashed?'機体損傷 — 組立棟で設計を見直してください':`T+ ${flight.time.toFixed(1)}s · 燃料 ${Math.round(flight.fuelRatio*100)}% · ${flight.started?'試験中':'点火待機'}`;if(now-infoTime>250){updateInfo();infoTime=now;}}
 controls.update();if(highlight.visible)highlight.update();renderer.render(scene,camera);}
requestAnimationFrame(animate);
function catalog(){const q=$('#search').value.toLowerCase();$('#parts').innerHTML=Object.entries(PARTS).filter(([k,d])=>(category==='すべて'||category===d.cat)&&(`${d.name} ${d.code} ${k}`).toLowerCase().includes(q)).map(([k,d])=>`<button class="partcard" data-type="${k}" title="${d.desc}"><span class="partcode">${d.code}</span><em>+</em><img src="${assets.get(k).userData.thumbnail}" alt=""><strong>${d.name}</strong></button>`).join('');$$('.partcard').forEach(b=>b.onclick=()=>beginPlacement(b.dataset.type));}
$('#categories').innerHTML=CATEGORIES.map(c=>`<button ${c===category?'class="active"':''}>${c}</button>`).join('');$$('#categories button').forEach(b=>b.onclick=()=>{category=b.textContent;$$('#categories button').forEach(x=>x.classList.toggle('active',x===b));catalog();});$('#search').oninput=catalog;
async function boot(){try{const loader=new GLTFLoader();await Promise.all(Object.keys(PARTS).map(async type=>{const gltf=await loader.loadAsync(`./assets/parts/${type}.glb`);assets.set(type,gltf.scene);}));const thumbRenderer=new T.WebGLRenderer({antialias:true,alpha:true,preserveDrawingBuffer:true});thumbRenderer.setSize(180,120);thumbRenderer.setPixelRatio(1);thumbRenderer.toneMapping=T.ACESFilmicToneMapping;thumbRenderer.toneMappingExposure=1.4;const ts=new T.Scene();ts.environment=scene.environment;ts.add(new T.HemisphereLight('#ffffff','#6e8998',3));const light=new T.DirectionalLight('#fff4db',4);light.position.set(4,6,5);ts.add(light);const tc=new T.PerspectiveCamera(33,1.5,.01,100);for(const [type,model]of assets){const clone=model.clone(true);ts.add(clone);const b=new T.Box3().setFromObject(clone),center=b.getCenter(new T.Vector3()),s=b.getSize(new T.Vector3()).length();tc.position.copy(center).add(new T.Vector3(1.3,.8,1.8).normalize().multiplyScalar(s*1.8));tc.lookAt(center);thumbRenderer.render(ts,tc);model.userData.thumbnail=thumbRenderer.domElement.toDataURL();ts.remove(clone);}thumbRenderer.dispose();catalog();rebuild();frame();$('#loading').hidden=true;}catch(e){console.error(e);$('#loading').innerHTML='<strong>部品を読み込めませんでした</strong><span>ページを再読み込みしてください。</span>';}}
boot();
